{
  "root_causes": [
    {
      "service": "ts-preserve-service",
      "fault_kind": "http_wrong_status_code",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT attr_http_response_status_code AS status, count(*) AS n FROM abnormal_traces WHERE service_name='ts-preserve-service' AND attr_span_kind='Client' AND span_name='POST' GROUP BY 1 ORDER BY 1",
          "claim": "In the incident, 537 of preserve's outgoing POST calls returned HTTP 401, while the other POSTs returned 200."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' AS period, count(*) AS order_post_server_spans FROM abnormal_traces WHERE service_name='ts-order-service' AND attr_span_kind='Server' AND span_name='POST /api/v1/orderservice/order' UNION ALL SELECT 'nor', count(*) FROM normal_traces WHERE service_name='ts-order-service' AND attr_span_kind='Server' AND span_name='POST /api/v1/orderservice/order'",
          "claim": "The order-create POST that preserve sends has no order-service server spans during the incident, versus 84 normally."
        },
        {
          "kind": "trace",
          "sql": "SELECT attr_http_response_status_code AS status, count(*) AS n FROM abnormal_traces WHERE service_name='ts-preserve-service' AND attr_span_kind='Server' GROUP BY 1 ORDER BY 1",
          "claim": "Every preserve server span in the incident returned HTTP 500, versus all 200 in the normal period."
        },
        {
          "kind": "log",
          "sql": "SELECT level, left(message,200) AS msg, count(*) AS n FROM abnormal_logs WHERE service_name='ts-preserve-service' AND level='SEVERE' GROUP BY 1,2 ORDER BY n DESC LIMIT 3",
          "claim": "Preserve logs 537 SEVERE exceptions: HttpClientErrorException Unauthorized 401 from a downstream call."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS parent_svc, c.service_name AS child_svc, c.attr_http_response_status_code AS child_status, count(*) AS n, round(quantile_cont(p.duration/1e6,0.5),1) AS ui_client_med_ms, round(quantile_cont(c.duration/1e6,0.5),1) AS preserve_server_med_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-preserve-service' GROUP BY 1,2,3",
          "claim": "ts-ui-dashboard calls to preserve return 500 with roughly 5.5 s client time, while preserve's own server span takes about 0.2 s."
        }
      ]
    }
  ]
}
